// Package store owns the SQLite file and every write the service performs.
package store

import (
	"context"
	"database/sql"
	"errors"
	"fmt"
	"strings"
	"sync"
	"time"

	_ "modernc.org/sqlite"
)

// Status values reported for a successful lock acquisition.
const (
	StatusAcquired  = "ACQUIRED"
	StatusReentered = "REENTERED"
	StatusWaiting   = "WAITING"
	StatusReleased  = "RELEASED"
)

// Error codes returned by ServiceError.
const (
	CodeMissingResourceID  = "MISSING_RESOURCE_ID"
	CodeMissingOwnerID     = "MISSING_OWNER_ID"
	CodeInvalidLease       = "INVALID_LEASE_SECONDS"
	CodeResourceNotFound   = "RESOURCE_NOT_FOUND"
	CodeNotOwner           = "NOT_OWNER"
	CodeLeaseExpired       = "LEASE_EXPIRED"
	CodeDuplicateWaiting   = "DUPLICATE_WAITING"
	CodeStorageUnavailable = "STORAGE_UNAVAILABLE"
)

// ServiceError carries the public error code while keeping SQL details hidden.
type ServiceError struct {
	Code    string
	Message string
}

func (e *ServiceError) Error() string { return e.Code + ": " + e.Message }

func serviceError(code, message string) *ServiceError {
	return &ServiceError{Code: code, Message: message}
}

// WaitingOwner is one queued request in the order it entered the queue.
type WaitingOwner struct {
	OwnerID              string `json:"ownerId"`
	RequestedLeaseSeconds int64  `json:"requestedLeaseSeconds"`
}

// State is the fixed, public view of one resource.
type State struct {
	ResourceID     string         `json:"resourceId"`
	OwnerID        string         `json:"ownerId,omitempty"`
	LeaseExpiresAt string         `json:"leaseExpiresAt,omitempty"`
	ReentryCount   int            `json:"reentryCount"`
	WaitingOwners  []WaitingOwner `json:"waitingOwners"`
}

// Store wraps the SQLite handle so callers never touch database/sql directly.
type Store struct {
	mu sync.Mutex
	db *sql.DB

	now func() time.Time
}

// Open prepares the database file and the schema this service needs.
func Open(path string) (*Store, error) {
	db, err := sql.Open("sqlite", path)
	if err != nil {
		return nil, fmt.Errorf("open sqlite: %w", err)
	}
	if _, err := db.Exec("PRAGMA journal_mode=WAL"); err != nil {
		db.Close()
		return nil, fmt.Errorf("enable wal: %w", err)
	}
	if _, err := db.Exec("PRAGMA busy_timeout=5000"); err != nil {
		db.Close()
		return nil, fmt.Errorf("set busy timeout: %w", err)
	}
	if _, err := db.Exec(schema); err != nil {
		db.Close()
		return nil, fmt.Errorf("apply schema: %w", err)
	}
	return &Store{db: db, now: time.Now}, nil
}

// SetClock overrides the time source used for lease decisions. Tests only.
func (s *Store) SetClock(now func() time.Time) {
	if now == nil {
		now = time.Now
	}
	s.now = now
}

// Ping reports whether the storage layer is usable.
func (s *Store) Ping() error { return s.db.Ping() }

// Close releases the database handle.
func (s *Store) Close() error { return s.db.Close() }

const schema = `
CREATE TABLE IF NOT EXISTS service_metadata (
	key   TEXT PRIMARY KEY,
	value TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS resources (
	resource_id      TEXT PRIMARY KEY,
	owner_id         TEXT NOT NULL DEFAULT '',
	lease_expires_ms INTEGER NOT NULL DEFAULT 0,
	reentry_count    INTEGER NOT NULL DEFAULT 0,
	updated_at_ms    INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS waiting_owners (
	id                    INTEGER PRIMARY KEY AUTOINCREMENT,
	resource_id           TEXT NOT NULL REFERENCES resources(resource_id),
	owner_id              TEXT NOT NULL,
	requested_lease_seconds INTEGER NOT NULL,
	UNIQUE (resource_id, owner_id)
);
`

// writeTx runs fn inside a serialized write transaction. The single process mutex plus
// SQLite's immediate transactions guarantee a resource never observes two holders and
// queued requests are neither lost nor duplicated.
func (s *Store) writeTx(ctx context.Context, fn func(*sql.Tx) error) error {
	s.mu.Lock()
	defer s.mu.Unlock()

	tx, err := s.db.BeginTx(ctx, &sql.TxOptions{Isolation: sql.LevelSerializable})
	if err != nil {
		return fmt.Errorf("begin tx: %w", err)
	}
	if err := fn(tx); err != nil {
		if rbErr := tx.Rollback(); rbErr != nil && !errors.Is(rbErr, sql.ErrTxDone) {
			return fmt.Errorf("%w (rollback: %v)", err, rbErr)
		}
		return err
	}
	if err := tx.Commit(); err != nil {
		return fmt.Errorf("commit tx: %w", err)
	}
	return nil
}

// Acquire grants the lock, re-enters it for the current owner, or queues the request.
// Reconciliation of an expired lease happens deterministically before any decision.
func (s *Store) Acquire(ctx context.Context, resourceID, ownerID string, leaseSeconds int64) (*State, string, error) {
	resourceID = strings.TrimSpace(resourceID)
	ownerID = strings.TrimSpace(ownerID)
	if resourceID == "" {
		return nil, "", serviceError(CodeMissingResourceID, "resourceId is required")
	}
	if ownerID == "" {
		return nil, "", serviceError(CodeMissingOwnerID, "ownerId is required")
	}
	if leaseSeconds <= 0 {
		return nil, "", serviceError(CodeInvalidLease, "leaseSeconds must be greater than zero")
	}

	var state *State
	status := ""
	err := s.writeTx(ctx, func(tx *sql.Tx) error {
		st, found, expired, err := s.ensureAndReconcile(ctx, tx, resourceID)
		if err != nil {
			return err
		}
		_ = expired

		if st.OwnerID == ownerID {
			// Same owner: re-entry never touches the existing lease or expiry.
			st.ReentryCount++
			if _, err := tx.ExecContext(ctx,
				"UPDATE resources SET reentry_count = ?, updated_at_ms = ? WHERE resource_id = ?",
				st.ReentryCount, s.now().UnixMilli(), resourceID); err != nil {
				return fmt.Errorf("increment reentry: %w", err)
			}
			status = StatusReentered
			state = st
			return nil
		}

		queued, err := s.alreadyWaiting(ctx, tx, resourceID, ownerID)
		if err != nil {
			return err
		}
		if queued {
			// Committed reconciliation survives this late rejection.
			return serviceError(CodeDuplicateWaiting, "owner already has a waiting request for this resource")
		}

		if st.OwnerID == "" {
			if err := s.promote(ctx, tx, resourceID, ownerID, leaseSeconds); err != nil {
				return err
			}
			st, _, _, err = s.loadState(ctx, tx, resourceID)
			if err != nil {
				return err
			}
			status = StatusAcquired
			state = st
			return nil
		}

		if _, err := tx.ExecContext(ctx,
			"INSERT INTO waiting_owners (resource_id, owner_id, requested_lease_seconds) VALUES (?, ?, ?)",
			resourceID, ownerID, leaseSeconds); err != nil {
			return fmt.Errorf("enqueue owner: %w", err)
		}
		st.WaitingOwners = append(st.WaitingOwners, WaitingOwner{OwnerID: ownerID, RequestedLeaseSeconds: leaseSeconds})
		status = StatusWaiting
		state = st
		return nil
	})
	if err != nil {
		return nil, "", mapStorageError(err)
	}
	return state, status, nil
}

// Reenter adds one re-entry for the current holder without extending the lease.
func (s *Store) Reenter(ctx context.Context, resourceID, ownerID string) (*State, error) {
	resourceID = strings.TrimSpace(resourceID)
	ownerID = strings.TrimSpace(ownerID)
	if resourceID == "" {
		return nil, serviceError(CodeMissingResourceID, "resourceId is required")
	}
	if ownerID == "" {
		return nil, serviceError(CodeMissingOwnerID, "ownerId is required")
	}

	var state *State
