		if !found {
			return serviceError(CodeResourceNotFound, "resource does not exist")
		}
		if expired {
			return serviceError(CodeLeaseExpired, "lease has expired and the lock has moved on")
		}
		if st.OwnerID != ownerID {
			return serviceError(CodeNotOwner, "only the current holder may release the lock")
		}

		nowMillis := s.now().UnixMilli()
		if st.ReentryCount > 1 {
			st.ReentryCount--
			if _, err := tx.ExecContext(ctx,
				"UPDATE resources SET reentry_count = ?, updated_at_ms = ? WHERE resource_id = ?",
				st.ReentryCount, nowMillis, resourceID); err != nil {
