// Query reads the resource state without extending leases, moving queues, or unlocking.
func (s *Store) Query(ctx context.Context, resourceID string) (*State, error) {
	resourceID = strings.TrimSpace(resourceID)
	if resourceID == "" {
		return nil, serviceError(CodeMissingResourceID, "resourceId is required")
