// Package store owns the SQLite file and every write the service performs.
package store

import (
	"context"
	"database/sql"
	"errors"
	"fmt"
	"net/url"
	"strings"
	"sync"
	"time"

	_ "modernc.org/sqlite"
)

// Sentinel errors describe the outcomes callers of the lock lifecycle must distinguish.
var (
	// ErrIllegalArgument is returned when the resource id is empty or the lease is not positive.
	ErrIllegalArgument = errors.New("illegal argument")
	// ErrIllegalState is returned when the operation cannot complete against the current lock state.
	ErrIllegalState = errors.New("illegal state")
	// ErrUnknownResource is returned when the resource has never been locked or is currently unlocked.
	ErrUnknownResource = errors.New("unknown resource")
)

// Waiter describes one caller queued for a resource in arrival order.
type Waiter struct {
	Holder    string
	LeaseMS   int64
	Position  int
	Requested time.Time
}

// State is a consistent snapshot of one resource. Locked is false for unknown or unlocked resources.
type State struct {
	Resource  string
	Locked    bool
	Holder    string
	ExpiresAt time.Time
	Reentries int
	Waiters   []Waiter
	// Position is the 1-based queue position observed by the caller of Acquire, or 0 when the
	// caller holds the resource.
	Position int
}

// Store wraps the SQLite handle so callers never touch database/sql directly.
type Store struct {
	db    *sql.DB
	mu    sync.Mutex
	nowFn func() time.Time
}

// Open prepares the database file and the schema this service needs.
func Open(path string) (*Store, error) {
	dsn := url.URL{Scheme: "file", Path: path}
	query := url.Values{}
	query.Add("_txlock", "immediate")
	query.Add("_pragma", "busy_timeout(5000)")
	dsn.RawQuery = query.Encode()

	db, err := sql.Open("sqlite", dsn.String())
	if err != nil {
		return nil, fmt.Errorf("open sqlite: %w", err)
	}
	db.SetMaxOpenConns(1)
	if _, err := db.Exec("PRAGMA journal_mode=WAL"); err != nil {
		db.Close()
		return nil, fmt.Errorf("enable wal: %w", err)
	}
	if _, err := db.Exec(schema); err != nil {
		db.Close()
		return nil, fmt.Errorf("apply schema: %w", err)
	}

	return &Store{
		db:    db,
		nowFn: time.Now,
	}, nil
}

// Ping reports whether the storage layer is usable.
func (s *Store) Ping() error { return s.db.Ping() }

// Close releases the database handle.
func (s *Store) Close() error { return s.db.Close() }

// Acquire registers an acquisition request from holder for resource with a lease of leaseMS
// milliseconds. The same holder re-entering a resource it owns increments the reentry count while
// keeping the original holder relation and expiry. Different holders are appended to the waiting
// queue in arrival order. If the current lease has expired, ownership either passes to the head
// waiter (one holder at a time) or to the caller directly when the queue is empty.
func (s *Store) Acquire(ctx context.Context, resource, holder string, leaseMS int64) (*State, error) {
	if err := validateArguments(resource, holder, leaseMS); err != nil {
		return nil, err
	}
	now := s.nowFn()

	s.mu.Lock()
	defer s.mu.Unlock()
	tx, err := s.db.BeginTx(ctx, nil)
	if err != nil {
		return nil, fmt.Errorf("begin acquire: %w", err)
	}
	defer tx.Rollback()

	state, err := loadState(ctx, tx, resource, now)
	if err != nil {
		return nil, err
	}

	switch {
	case !state.Locked:
		expiresAt := now.Add(time.Duration(leaseMS) * time.Millisecond)
		if err := insertLock(ctx, tx, resource, holder, expiresAt); err != nil {
			return nil, err
		}
		state.Locked = true
		state.Holder = holder
		state.ExpiresAt = expiresAt
		state.Reentries = 1
		state.Position = 0
	case state.Holder == holder:
		if _, err := tx.ExecContext(ctx,
			`UPDATE resource_locks SET reentries = reentries + 1 WHERE resource = ?`, resource); err != nil {
			return nil, fmt.Errorf("record reentry: %w", err)
		}
		state.Reentries++
		state.Position = 0
	default:
		for _, waiter := range state.Waiters {
			if waiter.Holder == holder {
				state.Position = waiter.Position
				return state, commitTx(tx)
			}
		}
		if err := insertWaiter(ctx, tx, resource, holder, leaseMS, now); err != nil {
			return nil, err
		}
		state.Waiters = append(state.Waiters, Waiter{
			Holder:    holder,
			LeaseMS:   leaseMS,
			Position:  len(state.Waiters) + 1,
			Requested: now,
		})
		state.Position = len(state.Waiters)
	}
	return state, commitTx(tx)
}

// Release removes one reentry level of holder's ownership. Ownership changes only after the number
// of releases equals the reentry count; then the head waiter becomes the new holder with its own
// fresh lease, or the resource becomes unlocked. Releasing without ownership, or releasing an
// unknown or unlocked resource, fails with ErrIllegalState.
func (s *Store) Release(ctx context.Context, resource, holder string) (*State, error) {
	if strings.TrimSpace(resource) == "" || strings.TrimSpace(holder) == "" {
		return nil, fmt.Errorf("%w: resource and holder must not be empty", ErrIllegalArgument)
	}
	now := s.nowFn()

	s.mu.Lock()
	defer s.mu.Unlock()
	tx, err := s.db.BeginTx(ctx, nil)
	if err != nil {
		return nil, fmt.Errorf("begin release: %w", err)
	}
	defer tx.Rollback()

	state, err := loadState(ctx, tx, resource, now)
	if err != nil {
		return nil, err
	}
	if !state.Locked {
		return nil, fmt.Errorf("%w: resource %q is not locked", ErrIllegalState, resource)
	}
	if state.Holder != holder {
		return nil, fmt.Errorf("%w: holder %q does not own resource %q", ErrIllegalState, holder, resource)
	}

	state.Reentries--
	if state.Reentries > 0 {
		if _, err := tx.ExecContext(ctx,
			`UPDATE resource_locks SET reentries = ? WHERE resource = ?`, state.Reentries, resource); err != nil {
			return nil, fmt.Errorf("record release: %w", err)
		}
		return state, commitTx(tx)
	}

	if len(state.Waiters) == 0 {
		if err := deleteLock(ctx, tx, resource); err != nil {
			return nil, err
		}
		state = &State{Resource: resource, Locked: false, Waiters: []Waiter{}}
		return state, commitTx(tx)
	}

	next := state.Waiters[0]
	expiresAt := now.Add(time.Duration(next.LeaseMS) * time.Millisecond)
	if err := transferLock(ctx, tx, resource, next.Holder, expiresAt); err != nil {
		return nil, err
	}
	state.Holder = next.Holder
	state.ExpiresAt = expiresAt
	state.Reentries = 1
	state.Waiters = state.Waiters[1:]
	state.Position = 0
	return state, commitTx(tx)
}

// GetState returns a consistent snapshot of resource, applying any lease expiry that is currently
// observable. Unknown or unlocked resources return ErrUnknownResource.
func (s *Store) GetState(ctx context.Context, resource string) (*State, error) {
	if strings.TrimSpace(resource) == "" {
		return nil, fmt.Errorf("%w: resource must not be empty", ErrIllegalArgument)
	}
	now := s.nowFn()

	s.mu.Lock()
	defer s.mu.Unlock()
	tx, err := s.db.BeginTx(ctx, nil)
	if err != nil {
		return nil, fmt.Errorf("begin get state: %w", err)
	}
	defer tx.Rollback()

	state, err := loadState(ctx, tx, resource, now)
	if err != nil {
		return nil, err
	}
	if !state.Locked {
		return nil, fmt.Errorf("%w: resource %q", ErrUnknownResource, resource)
	}
	return state, tx.Commit()
}

func validateArguments(resource, holder string, leaseMS int64) error {
	switch {
	case strings.TrimSpace(resource) == "":
		return fmt.Errorf("%w: resource must not be empty", ErrIllegalArgument)
	case strings.TrimSpace(holder) == "":
		return fmt.Errorf("%w: holder must not be empty", ErrIllegalArgument)
	case leaseMS <= 0:
		return fmt.Errorf("%w: lease must be positive", ErrIllegalArgument)
	default:
		return nil
	}
}

type lockRow struct {
	holder    string
	expiresAt int64
	reentries int
}

func loadLock(ctx context.Context, tx *sql.Tx, resource string) (*lockRow, error) {
	row := tx.QueryRowContext(ctx,
		`SELECT holder, expires_at, reentries FROM resource_locks WHERE resource = ?`, resource)
	var locked lockRow
	if err := row.Scan(&locked.holder, &locked.expiresAt, &locked.reentries); err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return nil, nil
		}
		return nil, fmt.Errorf("load lock: %w", err)
	}
	return &locked, nil
}

func loadWaiters(ctx context.Context, tx *sql.Tx, resource string) ([]Waiter, error) {
	rows, err := tx.QueryContext(ctx,
		`SELECT holder, lease_ms, requested_at FROM resource_waiters WHERE resource = ? ORDER BY seq ASC`, resource)
	if err != nil {
		return nil, fmt.Errorf("load waiters: %w", err)
	}
	defer rows.Close()

	waiters := []Waiter{}
	position := 1
	for rows.Next() {
		var waiter Waiter
		var requested int64
		if err := rows.Scan(&waiter.Holder, &waiter.LeaseMS, &requested); err != nil {
			return nil, fmt.Errorf("scan waiter: %w", err)
		}
		waiter.Position = position
		waiter.Requested = time.UnixMilli(requested)
		waiters = append(waiters, waiter)
		position++
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("iterate waiters: %w", err)
	}
	return waiters, nil
}

// loadState reads the lock and its queue and applies an observable expiry. Expired ownership
// passes to exactly one waiter, or unlocks the resource when nobody is waiting.
func loadState(ctx context.Context, tx *sql.Tx, resource string, now time.Time) (*State, error) {
	locked, err := loadLock(ctx, tx, resource)
	if err != nil {
		return nil, err
	}
	waiters, err := loadWaiters(ctx, tx, resource)
	if err != nil {
		return nil, err
	}

	state := &State{Resource: resource, Waiters: waiters}
	if locked == nil {
		return state, nil
	}
	expiresAt := time.UnixMilli(locked.expiresAt)
	if now.Before(expiresAt) {
		state.Locked = true
		state.Holder = locked.holder
		state.ExpiresAt = expiresAt
		state.Reentries = locked.reentries
		return state, nil
	}

	if len(waiters) == 0 {
		if err := deleteLock(ctx, tx, resource); err != nil {
			return nil, err
		}
		return state, nil
	}

	next := waiters[0]
	newExpiresAt := now.Add(time.Duration(next.LeaseMS) * time.Millisecond)
	if err := transferLock(ctx, tx, resource, next.Holder, newExpiresAt); err != nil {
		return nil, err
	}
	state.Locked = true
	state.Holder = next.Holder
	state.ExpiresAt = newExpiresAt
	state.Reentries = 1
	state.Waiters = waiters[1:]
	return state, nil
}

func insertLock(ctx context.Context, tx *sql.Tx, resource, holder string, expiresAt time.Time) error {
	if _, err := tx.ExecContext(ctx,
		`INSERT INTO resource_locks (resource, holder, expires_at, reentries) VALUES (?, ?, ?, 1)`,
		resource, holder, expiresAt.UnixMilli()); err != nil {
		return fmt.Errorf("insert lock: %w", err)
	}
	return nil
}

func insertWaiter(ctx context.Context, tx *sql.Tx, resource, holder string, leaseMS int64, now time.Time) error {
	if _, err := tx.ExecContext(ctx,
		`INSERT INTO resource_waiters (resource, holder, lease_ms, requested_at) VALUES (?, ?, ?, ?)`,
		resource, holder, leaseMS, now.UnixMilli()); err != nil {
		return fmt.Errorf("insert waiter: %w", err)
	}
	return nil
}

func deleteLock(ctx context.Context, tx *sql.Tx, resource string) error {
	if _, err := tx.ExecContext(ctx, `DELETE FROM resource_locks WHERE resource = ?`, resource); err != nil {
		return fmt.Errorf("delete lock: %w", err)
	}
	return nil
}

func transferLock(ctx context.Context, tx *sql.Tx, resource, holder string, expiresAt time.Time) error {
	if _, err := tx.ExecContext(ctx,
		`UPDATE resource_locks SET holder = ?, expires_at = ?, reentries = 1 WHERE resource = ?`,
		holder, expiresAt.UnixMilli(), resource); err != nil {
		return fmt.Errorf("transfer lock: %w", err)
	}
	if _, err := tx.ExecContext(ctx,
		`DELETE FROM resource_waiters WHERE resource = ? AND holder = ?`, resource, holder); err != nil {
		return fmt.Errorf("consume head waiter: %w", err)
	}
	return nil
}

func commitTx(tx *sql.Tx) error {
	if err := tx.Commit(); err != nil {
		return fmt.Errorf("commit: %w", err)
	}
	return nil
}

const schema = `
CREATE TABLE IF NOT EXISTS service_metadata (
	key   TEXT PRIMARY KEY,
	value TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS resource_locks (
	resource   TEXT PRIMARY KEY,
	holder     TEXT NOT NULL,
	expires_at INTEGER NOT NULL,
	reentries  INTEGER NOT NULL CHECK (reentries > 0)
);

CREATE TABLE IF NOT EXISTS resource_waiters (
	resource     TEXT NOT NULL,
	holder       TEXT NOT NULL,
	lease_ms     INTEGER NOT NULL CHECK (lease_ms > 0),
	requested_at INTEGER NOT NULL,
	seq          INTEGER PRIMARY KEY AUTOINCREMENT
);

CREATE UNIQUE INDEX IF NOT EXISTS idx_resource_waiters_resource_holder
	ON resource_waiters (resource, holder);
CREATE INDEX IF NOT EXISTS idx_resource_waiters_resource_seq
	ON resource_waiters (resource, seq);
`

