+			return serviceError(CodeLeaseExpired, "the lease has expired; late reentry is rejected")
+		}
+		if !st.HasOwner || st.OwnerID != ownerID {
+			return serviceError(CodeNotOwner, "only the current holder may reenter")
+		}
+		if err := s.bumpReentry(ctx, tx, resourceID, st.ReentryCount); err != nil {
+			return err
+		}
+		st.ReentryCount++
+		state = st
+		return nil
+	})
