+	err := s.writeTx(ctx, func(tx *sql.Tx) error {
+		st, found, err := s.loadState(ctx, tx, resourceID)
+		if err != nil {
+			return err
+		}
+		if !found {
+			return serviceError(CodeNotOwner, "only the current holder may release")
+		}
+		wasExpiredHolder := st.HasOwner && st.OwnerID == ownerID && !st.LeaseExpiresAt.After(s.nowFn())
+		if err := s.reconcileExpiry(ctx, tx, &st); err != nil {
+			return err
+		}
+		if wasExpiredHolder {
+			return serviceError(CodeLeaseExpired, "the lease has expired; late release is rejected")
+		}
+		if !st.HasOwner || st.OwnerID != ownerID {
+			return serviceError(CodeNotOwner, "only the current holder may release")
+		}
+		if st.ReentryCount > 1 {
+			if err := s.decReentry(ctx, tx, resourceID, st.ReentryCount); err != nil {
