+	state := State{ResourceID: resourceID, WaitingOwners: []WaitingOwner{}}
+	var ownerID string
+	var expiresMillis, reentryCount int64
+	err := q.QueryRowContext(ctx,
+		`SELECT owner_id, lease_expires_ms, reentry_count FROM resources WHERE resource_id = ?1`,
+		resourceID).Scan(&ownerID, &expiresMillis, &reentryCount)
