	st.SetClockForTest(func() time.Time { return now })
	return st, &now
}

func ctx() context.Context { return context.Background() }

func TestAcquireAndQuerySnapshot(t *testing.T) {
	st, _ := newTestStore(t)

	state, err := st.Acquire(ctx(), "doc", "alice", 5000)
	if err != nil {
		t.Fatalf("acquire: %v", err)
	}
	if !state.Locked || state.Holder != "alice" || state.Reentries != 1 {
		t.Fatalf("unexpected state: %+v", state)
	}
	if len(state.Waiters) != 0 {
		t.Fatalf("waiters = %v, want empty", state.Waiters)
	}
	wantExpiry := time.Date(2026, 10, 1, 12, 0, 5, 0, time.UTC)
	if !state.ExpiresAt.Equal(wantExpiry) {
		t.Fatalf("expires = %v, want %v", state.ExpiresAt, wantExpiry)
	}

	got, err := st.GetState(ctx(), "doc")
	if err != nil {
		t.Fatalf("get state: %v", err)
	}
	if got.Holder != "alice" || got.Reentries != 1 || !got.ExpiresAt.Equal(wantExpiry) {
		t.Fatalf("snapshot mismatch: %+v", got)
	}
}

func TestReentryKeepsHolderAndExpiry(t *testing.T) {
