func TestDifferentHoldersQueueInArrivalOrder(t *testing.T) {
	st, _ := newTestStore(t)

	if _, err := st.Acquire(ctx(), "doc", "alice", 5000); err != nil {
		t.Fatalf("acquire alice: %v", err)
	}
	bob, err := st.Acquire(ctx(), "doc", "bob", 3000)
	if err != nil {
		t.Fatalf("acquire bob: %v", err)
	}
	if bob.Holder != "alice" || bob.Position != 1 {
		t.Fatalf("bob position = %d holder = %s", bob.Position, bob.Holder)
	}
	carol, err := st.Acquire(ctx(), "doc", "carol", 3000)
	if err != nil {
		t.Fatalf("acquire carol: %v", err)
	}
	if carol.Position != 2 || len(carol.Waiters) != 2 {
		t.Fatalf("carol snapshot = %+v", carol)
	}
	if carol.Waiters[0].Holder != "bob" || carol.Waiters[1].Holder != "carol" {
		t.Fatalf("queue order = %+v", carol.Waiters)
	}

	// A repeated request from a queued holder is idempotent: it observes its position once.
	again, err := st.Acquire(ctx(), "doc", "bob", 3000)
	if err != nil {
