		t.Fatalf("queue bob: %v", err)
	}

	afterFirst, err := st.Release(ctx(), "doc", "alice")
	if err != nil {
		t.Fatalf("first release: %v", err)
	}
	if afterFirst.Holder != "alice" || afterFirst.Reentries != 1 || len(afterFirst.Waiters) != 1 {
		t.Fatalf("lock handed over early: %+v", afterFirst)
	}

	afterSecond, err := st.Release(ctx(), "doc", "alice")
	if err != nil {
		t.Fatalf("second release: %v", err)
	}
	if afterSecond.Holder != "bob" || afterSecond.Reentries != 1 {
		t.Fatalf("new holder = %s reentries = %d", afterSecond.Holder, afterSecond.Reentries)
	}
	if len(afterSecond.Waiters) != 0 {
		t.Fatalf("bob should have left the queue: %+v", afterSecond.Waiters)
	}
	wantExpiry := time.Date(2026, 10, 1, 12, 0, 3, 0, time.UTC)
	if !afterSecond.ExpiresAt.Equal(wantExpiry) {
		t.Fatalf("bob expiry = %v, want %v", afterSecond.ExpiresAt, wantExpiry)
	}
}

