func TestExpiryTransfersToSingleHeadWaiter(t *testing.T) {
	st, now := newTestStore(t)

	if _, err := st.Acquire(ctx(), "doc", "alice", 1000); err != nil {
		t.Fatalf("acquire alice: %v", err)
	}
	if _, err := st.Acquire(ctx(), "doc", "bob", 3000); err != nil {
		t.Fatalf("queue bob: %v", err)
	}
	if _, err := st.Acquire(ctx(), "doc", "carol", 4000); err != nil {
		t.Fatalf("queue carol: %v", err)
	}
	if _, err := st.Acquire(ctx(), "doc", "alice", 2000); err != nil {
		t.Fatalf("alice reentry: %v", err)
	}

	*now = now.Add(1001 * time.Millisecond)

	state, err := st.GetState(ctx(), "doc")
	if err != nil {
		t.Fatalf("get state after expiry: %v", err)
	}
	if state.Holder != "bob" || state.Reentries != 1 {
		t.Fatalf("post-expiry holder = %s reentries = %d", state.Holder, state.Reentries)
	}
	if len(state.Waiters) != 1 || state.Waiters[0].Holder != "carol" {
		t.Fatalf("post-expiry queue = %+v", state.Waiters)
	}
	wantExpiry := now.Add(3000 * time.Millisecond)
	if !state.ExpiresAt.Equal(wantExpiry) {
		t.Fatalf("bob expiry = %v, want %v", state.ExpiresAt, wantExpiry)
	}

	// The old holder relationship is dead: releases and reentries are rejected.
	if _, err := st.Release(ctx(), "doc", "alice"); !errors.Is(err, ErrIllegalState) {
