		t.Fatalf("stale holder re-acquire should queue, got %v", err)
	} else {
		state, _ := st.GetState(ctx(), "doc")
		if state.Holder != "bob" {
			t.Fatalf("stale holder must not reclaim, holder = %s", state.Holder)
		}
	}
}

