func TestConcurrentAcquiresProduceSingleHolderAndFifoQueue(t *testing.T) {
	st, _ := newTestStore(t)

	const callers = 32
	start := make(chan struct{})
	errs := make(chan error, callers)
	results := make(chan *State, callers)
	for i := 0; i < callers; i++ {
		holder := "holder-" + strconvItoa(i)
		go func() {
			<-start
			state, err := st.Acquire(context.Background(), "hot", holder, 10_000)
			if err != nil {
				errs <- err
				return
			}
			results <- state
		}()
	}
	close(start)

	holders := 0
	queued := 0
	queuePositions := map[int]string{}
	for i := 0; i < callers; i++ {
		select {
		case err := <-errs:
			t.Fatalf("concurrent acquire: %v", err)
		case state := <-results:
			if state.Position == 0 {
				holders++
			} else {
				queued++
				if _, dup := queuePositions[state.Position]; dup {
					t.Fatalf("duplicate queue position %d", state.Position)
				}
				queuePositions[state.Position] = state.Holder
			}
		}
	}
	if holders != 1 {
		t.Fatalf("holders = %d, want exactly 1", holders)
	}
	if queued != callers-1 {
		t.Fatalf("queued = %d, want %d", queued, callers-1)
	}
	for position := 1; position <= queued; position++ {
		if queuePositions[position] == "" {
			t.Fatalf("missing queue position %d", position)
		}
	}

	snapshot, err := st.GetState(context.Background(), "hot")
	if err != nil {
		t.Fatalf("get state: %v", err)
	}
	if len(snapshot.Waiters) != callers-1 {
		t.Fatalf("snapshot queue length = %d", len(snapshot.Waiters))
	}
}

func TestConcurrentExpiryAndAcquireTransferOnce(t *testing.T) {
	st, now := newTestStore(t)

	if _, err := st.Acquire(context.Background(), "doc", "alice", 1000); err != nil {
		t.Fatalf("acquire alice: %v", err)
	}
	if _, err := st.Acquire(context.Background(), "doc", "bob", 3000); err != nil {
		t.Fatalf("queue bob: %v", err)
	}
	if _, err := st.Acquire(context.Background(), "doc", "carol", 3000); err != nil {
		t.Fatalf("queue carol: %v", err)
	}
	*now = now.Add(1001 * time.Millisecond)

	const workers = 16
	start := make(chan struct{})
	done := make(chan *State, workers)
	for i := 0; i < workers; i++ {
		go func() {
			<-start
			state, err := st.GetState(context.Background(), "doc")
			if err != nil {
				t.Errorf("get state: %v", err)
				return
			}
			done <- state
		}()
	}
	close(start)
	for i := 0; i < workers; i++ {
		state := <-done
		if state.Holder != "bob" {
			t.Fatalf("holder = %q, want bob", state.Holder)
		}
		if state.Reentries != 1 {
			t.Fatalf("reentries = %d, want 1", state.Reentries)
		}
