package api

import (
	"errors"
	"net/http"

	"github.com/gin-gonic/gin"

	"github.com/luwa07832/distributed-lock-service/internal/store"
)

// NewRouter wires the public HTTP surface. Every entry keeps the error shape published in
// README.md: a single top-level "error" object with string "code" and "message" fields, never
// exposing SQL, stack traces or file paths.
func NewRouter(st *store.Store) *gin.Engine {
	gin.SetMode(gin.ReleaseMode)
	router := gin.New()
	router.Use(gin.Recovery())

	router.GET("/healthz", healthz(st))
	router.POST("/locks/:resource/acquire", acquire(st))
	router.POST("/locks/:resource/release", release(st))
	router.GET("/locks/:resource", getState(st))

	router.NoRoute(func(c *gin.Context) {
		c.JSON(http.StatusNotFound, gin.H{"error": gin.H{"code": "route_not_found", "message": "no route matches this path"}})
	})
	return router
}

func healthz(st *store.Store) gin.HandlerFunc {
	return func(c *gin.Context) {
		if err := st.Ping(); err != nil {
			c.JSON(http.StatusServiceUnavailable, gin.H{"error": gin.H{"code": "storage_unavailable", "message": "database is not available"}})
			return
		}
		c.JSON(http.StatusOK, gin.H{"status": "ok", "database": "ok"})
	}
}

type acquireRequest struct {
	Holder  string `json:"holder"`
	LeaseMS int64  `json:"lease_ms"`
}

type releaseRequest struct {
	Holder string `json:"holder"`
}

type waiterView struct {
	Holder   string `json:"holder"`
	LeaseMS  int64  `json:"lease_ms"`
	Position int    `json:"position"`
}

type stateView struct {
	Resource  string       `json:"resource"`
	Locked    bool         `json:"locked"`
	Holder    string       `json:"holder,omitempty"`
	ExpiresAt string       `json:"expires_at,omitempty"`
	Reentries int          `json:"reentries,omitempty"`
	Position  int          `json:"position,omitempty"`
	Waiters   []waiterView `json:"waiters"`
}

func acquire(st *store.Store) gin.HandlerFunc {
	return func(c *gin.Context) {
		var request acquireRequest
		if err := c.ShouldBindJSON(&request); err != nil {
			writeError(c, http.StatusBadRequest, "invalid_request", "request body must be valid JSON containing holder and lease_ms")
			return
		}
		state, err := st.Acquire(c.Request.Context(), c.Param("resource"), request.Holder, request.LeaseMS)
		if err != nil {
			writeStoreError(c, err)
			return
		}
		c.JSON(http.StatusOK, toStateView(state))
	}
}

func release(st *store.Store) gin.HandlerFunc {
	return func(c *gin.Context) {
		var request releaseRequest
		if err := c.ShouldBindJSON(&request); err != nil {
			writeError(c, http.StatusBadRequest, "invalid_request", "request body must be valid JSON containing holder")
			return
		}
		state, err := st.Release(c.Request.Context(), c.Param("resource"), request.Holder)
		if err != nil {
			writeStoreError(c, err)
			return
		}
		c.JSON(http.StatusOK, toStateView(state))
	}
}

func getState(st *store.Store) gin.HandlerFunc {
	return func(c *gin.Context) {
		state, err := st.GetState(c.Request.Context(), c.Param("resource"))
		if err != nil {
			writeStoreError(c, err)
			return
		}
		c.JSON(http.StatusOK, toStateView(state))
	}
}

func toStateView(state *store.State) stateView {
	view := stateView{
		Resource: state.Resource,
		Locked:   state.Locked,
		Waiters:  []waiterView{},
	}
	if state.Locked {
		view.Holder = state.Holder
		view.ExpiresAt = state.ExpiresAt.UTC().Format("2006-01-02T15:04:05.999999999Z07:00")
		view.Reentries = state.Reentries
		view.Position = state.Position
	}
	for _, waiter := range state.Waiters {
		view.Waiters = append(view.Waiters, waiterView{
			Holder:   waiter.Holder,
			LeaseMS:  waiter.LeaseMS,
			Position: waiter.Position,
		})
	}
	return view
}

func writeStoreError(c *gin.Context, err error) {
	switch {
	case errors.Is(err, store.ErrIllegalArgument):
		writeError(c, http.StatusBadRequest, "illegal_argument", err.Error())
	case errors.Is(err, store.ErrIllegalState):
		writeError(c, http.StatusConflict, "illegal_state", err.Error())
	case errors.Is(err, store.ErrUnknownResource):
		writeError(c, http.StatusNotFound, "unknown_resource", "resource is not locked")
	default:
		writeError(c, http.StatusInternalServerError, "storage_unavailable", "database operation failed")
	}
}

// writeError emits the published error shape. The message is always a stable string so internal
// details wrapped onto sentinel errors never leak to callers.
func writeError(c *gin.Context, status int, code, message string) {
	switch code {
	case "illegal_argument":
		message = "resource and holder must be non-empty and lease_ms must be positive"
	case "illegal_state":
		message = "the lock is not in a state that allows this operation"
	}
	c.JSON(status, gin.H{"error": gin.H{"code": code, "message": message}})
}
