package api

import (
	"bytes"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"path/filepath"
	"strconv"
	"testing"

	"github.com/gin-gonic/gin"

	"github.com/luwa07832/distributed-lock-service/internal/store"
)

type lockClient struct {
	t      *testing.T
	engine *gin.Engine
}

func newLockClient(t *testing.T) *lockClient {
	t.Helper()
	st, err := store.Open(filepath.Join(t.TempDir(), "service.db"))
	if err != nil {
		t.Fatalf("open: %v", err)
	}
	t.Cleanup(func() { st.Close() })
	return &lockClient{t: t, engine: NewRouter(st)}
}

type stateResponse struct {
	Resource  string `json:"resource"`
	Locked    bool   `json:"locked"`
	Holder    string `json:"holder"`
	ExpiresAt string `json:"expires_at"`
	Reentries int    `json:"reentries"`
	Position  int    `json:"position"`
	Waiters   []struct {
		Holder   string `json:"holder"`
		LeaseMS  int64  `json:"lease_ms"`
		Position int    `json:"position"`
	} `json:"waiters"`
}

func (c *lockClient) call(method, path, body string) *httptest.ResponseRecorder {
	c.t.Helper()
	request := httptest.NewRequest(method, path, bytes.NewReader([]byte(body)))
	request.Header.Set("Content-Type", "application/json")
	recorder := httptest.NewRecorder()
	c.engine.ServeHTTP(recorder, request)
	return recorder
}

func (c *lockClient) acquire(resource, holder string, leaseMS int64) (*httptest.ResponseRecorder, stateResponse) {
	recorder := c.call(http.MethodPost, "/locks/"+resource+"/acquire",
		`{"holder":"`+holder+`","lease_ms":`+strconv.FormatInt(leaseMS, 10)+`}`)
	return recorder, decodeState(c.t, recorder)
}

func (c *lockClient) release(resource, holder string) (*httptest.ResponseRecorder, stateResponse) {
	recorder := c.call(http.MethodPost, "/locks/"+resource+"/release", `{"holder":"`+holder+`"}`)
	return recorder, decodeState(c.t, recorder)
}

func (c *lockClient) get(resource string) (*httptest.ResponseRecorder, stateResponse) {
	recorder := c.call(http.MethodGet, "/locks/"+resource, "")
	return recorder, decodeState(c.t, recorder)
}

func decodeState(t *testing.T, recorder *httptest.ResponseRecorder) stateResponse {
	t.Helper()
	if recorder.Code != http.StatusOK {
		t.Fatalf("status = %d body = %s", recorder.Code, recorder.Body.String())
	}
	var state stateResponse
	if err := json.Unmarshal(recorder.Body.Bytes(), &state); err != nil {
		t.Fatalf("decode: %v body=%s", err, recorder.Body.String())
	}
	return state
}

func assertErrorCode(t *testing.T, recorder *httptest.ResponseRecorder, want string) {
	t.Helper()
	var body struct {
		Error struct {
			Code    string `json:"code"`
			Message string `json:"message"`
		} `json:"error"`
	}
	if err := json.Unmarshal(recorder.Body.Bytes(), &body); err != nil {
		t.Fatalf("decode error body: %v", err)
	}
	if body.Error.Code != want {
		t.Fatalf("error code = %q, want %q", body.Error.Code, want)
	}
	if body.Error.Message == "" {
		t.Fatalf("error message empty")
	}
}

func TestAcquireReenterQueueReleaseLifecycle(t *testing.T) {
	client := newLockClient(t)

	recorder, state := client.acquire("doc", "alice", 5000)
	if recorder.Code != http.StatusOK || !state.Locked || state.Holder != "alice" || state.Reentries != 1 {
		t.Fatalf("acquire = %d %+v", recorder.Code, state)
	}
	if len(state.Waiters) != 0 {
		t.Fatalf("waiters = %v", state.Waiters)
	}

	recorder, state = client.acquire("doc", "alice", 9000)
	if recorder.Code != http.StatusOK || state.Reentries != 2 {
		t.Fatalf("reenter = %d %+v", recorder.Code, state)
	}

	recorder, state = client.acquire("doc", "bob", 3000)
	if recorder.Code != http.StatusOK || state.Position != 1 || state.Holder != "alice" || len(state.Waiters) != 1 {
		t.Fatalf("queue bob = %d %+v", recorder.Code, state)
	}

	recorder, state = client.acquire("doc", "carol", 4000)
	if recorder.Code != http.StatusOK || state.Position != 2 || len(state.Waiters) != 2 {
		t.Fatalf("queue carol = %d %+v", recorder.Code, state)
	}

	recorder, state = client.get("doc")
	if recorder.Code != http.StatusOK || state.Holder != "alice" || len(state.Waiters) != 2 {
		t.Fatalf("get = %d %+v", recorder.Code, state)
	}

	recorder, state = client.release("doc", "alice")
	if recorder.Code != http.StatusOK || state.Holder != "alice" || state.Reentries != 1 {
		t.Fatalf("first release must not hand over: %d %+v", recorder.Code, state)
	}

	recorder, state = client.release("doc", "alice")
	if recorder.Code != http.StatusOK || state.Holder != "bob" || state.Reentries != 1 {
		t.Fatalf("second release = %d %+v", recorder.Code, state)
	}
	if len(state.Waiters) != 1 || state.Waiters[0].Holder != "carol" {
		t.Fatalf("queue after transfer = %+v", state.Waiters)
	}
}

func TestFinalReleaseUnlocksAndIsUnknownAfterwards(t *testing.T) {
	client := newLockClient(t)
	client.acquire("doc", "alice", 5000)

	recorder, state := client.release("doc", "alice")
	if recorder.Code != http.StatusOK || state.Locked {
		t.Fatalf("release = %d %+v", recorder.Code, state)
	}

	recorder = client.call(http.MethodGet, "/locks/doc", "")
	if recorder.Code != http.StatusNotFound {
		t.Fatalf("get unlocked status = %d", recorder.Code)
	}
	assertErrorCode(t, recorder, "unknown_resource")
}

func TestValidationAndStateErrors(t *testing.T) {
	client := newLockClient(t)

	recorder := client.call(http.MethodPost, "/locks/%20/acquire", `{"holder":"alice","lease_ms":1000}`)
	if recorder.Code != http.StatusBadRequest {
		t.Fatalf("blank resource status = %d", recorder.Code)
	}
	assertErrorCode(t, recorder, "illegal_argument")

	recorder = client.call(http.MethodPost, "/locks/doc/acquire", `{"holder":"alice","lease_ms":0}`)
	if recorder.Code != http.StatusBadRequest {
		t.Fatalf("zero lease status = %d", recorder.Code)
	}
	assertErrorCode(t, recorder, "illegal_argument")

	recorder = client.call(http.MethodPost, "/locks/doc/acquire", `{"holder":"alice","lease_ms":-5}`)
	if recorder.Code != http.StatusBadRequest {
		t.Fatalf("negative lease status = %d", recorder.Code)
	}
	assertErrorCode(t, recorder, "illegal_argument")

	client.acquire("doc", "alice", 5000)

	recorder = client.call(http.MethodPost, "/locks/doc/release", `{"holder":"bob"}`)
	if recorder.Code != http.StatusConflict {
		t.Fatalf("wrong holder status = %d", recorder.Code)
	}
	assertErrorCode(t, recorder, "illegal_state")

	client.release("doc", "alice")
	recorder = client.call(http.MethodPost, "/locks/doc/release", `{"holder":"alice"}`)
	if recorder.Code != http.StatusConflict {
		t.Fatalf("double release status = %d", recorder.Code)
	}
	assertErrorCode(t, recorder, "illegal_state")
}

