package store

import (
	"context"
	"errors"
	"path/filepath"
	"strconv"
	"sync"
	"testing"
	"time"
)

func newTestStore(t *testing.T) (*Store, *time.Time) {
	t.Helper()
	st, err := Open(filepath.Join(t.TempDir(), "store.db"))
	if err != nil {
		t.Fatalf("open: %v", err)
	}
	t.Cleanup(func() { st.Close() })

	now := time.Date(2026, 10, 1, 12, 0, 0, 0, time.UTC)
	st.SetClockForTest(func() time.Time { return now })
	return st, &now
}

func bg() context.Context { return context.Background() }

func wantCode(t *testing.T, err error, code string) {
	t.Helper()
	var serviceErr *ServiceError
	if !errors.As(err, &serviceErr) {
		t.Fatalf("err = %v, want ServiceError %s", err, code)
	}
	if serviceErr.Code != code {
		t.Fatalf("code = %s, want %s", serviceErr.Code, code)
	}
}

func TestAcquireFirstHolderAndSnapshot(t *testing.T) {
	st, _ := newTestStore(t)

	state, status, err := st.Acquire(bg(), "doc", "alice", 5)
	if err != nil {
		t.Fatalf("acquire: %v", err)
	}
	if status != StatusAcquired {
		t.Fatalf("status = %s", status)
	}
	if state.OwnerID != "alice" || state.ReentryCount != 1 {
		t.Fatalf("unexpected state: %+v", state)
	}
	if len(state.WaitingOwners) != 0 {
		t.Fatalf("waiting owners = %v, want empty", state.WaitingOwners)
	}
	wantExpiry := time.Date(2026, 10, 1, 12, 0, 5, 0, time.UTC).Format(time.RFC3339Nano)
	if state.LeaseExpiresAt != wantExpiry {
		t.Fatalf("leaseExpiresAt = %s, want %s", state.LeaseExpiresAt, wantExpiry)
	}

	got, err := st.Query(bg(), "doc")
	if err != nil {
		t.Fatalf("query: %v", err)
	}
	if got.OwnerID != "alice" || got.ReentryCount != 1 || got.LeaseExpiresAt != wantExpiry {
		t.Fatalf("snapshot mismatch: %+v", got)
	}
}

func TestReentryKeepsHolderAndExpiry(t *testing.T) {
	st, _ := newTestStore(t)

	first, _, err := st.Acquire(bg(), "doc", "alice", 5)
	if err != nil {
		t.Fatalf("acquire: %v", err)
	}
	second, status, err := st.Acquire(bg(), "doc", "alice", 9)
	if err != nil {
		t.Fatalf("reenter via acquire: %v", err)
	}
	if status != StatusAcquired || second.ReentryCount != 2 {
		t.Fatalf("status = %s state = %+v", status, second)
	}
	if second.OwnerID != "alice" || second.LeaseExpiresAt != first.LeaseExpiresAt {
		t.Fatalf("holder/expiry changed: %+v vs %+v", second, first)
	}

	third, err := st.Reenter(bg(), "doc", "alice")
	if err != nil {
		t.Fatalf("reenter: %v", err)
	}
	if third.ReentryCount != 3 || third.LeaseExpiresAt != first.LeaseExpiresAt {
		t.Fatalf("reenter state = %+v", third)
	}
}

func TestWaitingFIFOAndDuplicateRejected(t *testing.T) {
	st, _ := newTestStore(t)

	if _, _, err := st.Acquire(bg(), "doc", "alice", 5); err != nil {
		t.Fatalf("acquire alice: %v", err)
	}
	bob, status, err := st.Acquire(bg(), "doc", "bob", 3)
	if err != nil {
		t.Fatalf("acquire bob: %v", err)
	}
	if status != StatusWaiting || bob.OwnerID != "alice" || len(bob.WaitingOwners) != 1 {
		t.Fatalf("bob state = %+v status = %s", bob, status)
	}
	carol, status, err := st.Acquire(bg(), "doc", "carol", 4)
	if err != nil {
		t.Fatalf("acquire carol: %v", err)
	}
	if status != StatusWaiting || len(carol.WaitingOwners) != 2 {
		t.Fatalf("carol state = %+v", carol)
	}
	if carol.WaitingOwners[0].OwnerID != "bob" || carol.WaitingOwners[0].RequestedLeaseSeconds != 3 {
		t.Fatalf("queue head = %+v", carol.WaitingOwners[0])
	}
	if carol.WaitingOwners[1].OwnerID != "carol" || carol.WaitingOwners[1].RequestedLeaseSeconds != 4 {
		t.Fatalf("queue tail = %+v", carol.WaitingOwners[1])
	}

	_, _, err = st.Acquire(bg(), "doc", "bob", 3)
	wantCode(t, err, CodeDuplicateWaiting)

	got, err := st.Query(bg(), "doc")
	if err != nil {
		t.Fatalf("query: %v", err)
	}
	if len(got.WaitingOwners) != 2 {
		t.Fatalf("duplicate was enqueued: %+v", got.WaitingOwners)
	}
}

func TestReleaseReentryLevelsThenTransfers(t *testing.T) {
	st, _ := newTestStore(t)

	if _, _, err := st.Acquire(bg(), "doc", "alice", 5); err != nil {
		t.Fatalf("acquire: %v", err)
	}
	if _, err := st.Reenter(bg(), "doc", "alice"); err != nil {
