	}
	now := s.nowFn()
	if expiresAt.After(now) {
		return state, "", nil
	}
	expiredOwner = state.OwnerID
	if err := s.promoteHead(ctx, tx, resourceID, expiredOwner); err != nil {
		return State{}, "", err

